      "ledger_id": "A4",
      "description": "Emailed landlord Ben Hartley about the emergency and the £300 approval limit (MSG-103)."
    },
    {
      "ledger_id": "A5",
      "description": "Texted HeatRight Ltd the emergency job details (MSG-104)."
    },
    {
      "ledger_id": "A6",
      "description": "Escalated P1 to maintenance as ESC-105."
    }
  ],
  "failed_actions": [],
  "conflicts": [
    "The tenant says the issue is \"not urgent\", but the described symptom is a possible gas leak. I trusted the symptom over the tenant's wording.",
